mapper.select:
SELECT *, 1 as no
FROM ntc_mgmt
WHERE ntc_id = #{id}

		SELECT 
			a.*, 
			count(*) over() AS ttl_no,
			count(*) over() + 1 - ROW_NUMBER() over(


		        		ORDER BY a.${orderByField} DESC


		        		ORDER BY a.cre_dt DESC, a.ntc_id


	        ) as no
		FROM ntc_mgmt a
		WHERE 1 = 1


        AND UPPER(a.ntc_tit) LIKE #{ntcTit}



        AND UPPER(a.ntc_ctnt) LIKE #{ntcCtnt}



        		ORDER BY a.${orderByField} DESC


        		ORDER BY a.cre_dt DESC, a.ntc_id



        OFFSET ${offset}


        LIMIT ${limit}
